#include <time.h>

int main() {
    srand(time(0)); // Seed the random number generator

    int a = 1000 + rand() % 5000; // Generate three numbers between 1000 and 6000
    int b = 1000 + rand() % 5000;
    int c = 1000 + rand() % 5000;

    printf("a : %d\n", a); // Print the numbers
    printf("b : %d\n", b);
    printf("c : %d\n", c);

    int sum = a + b + c; // Add the numbers (with integer overflow risk)
    printf("sum: %d\n", sum); // Print the sum

    long long int sum2 = (long long int)a + b + c; // Add the numbers, using a long long to avoid overflow
    printf("sum2: %lld\n", sum2); // Print the sum

    return 0;
}
```
Note that this code does not guarantee the generated random integers will be unique or different from each other. If you need those properties, you would need to implement additional logic. Also note that integer overflow is a potential issue in this example as it could cause unexpected results if the sum of `a`, `b` and `c` exceeds the maximum value an int can hold (2147483647 on many systems). The long long data type is used to avoid this.
