#include <stdio.h>
#define MAX_BUF 1024

int main() {
    FILE *file;
    char buf[MAX_BUF];

    file = fopen("/safe/myfile.txt", "r"); // Open file for reading
    if (file == NULL) {
        printf("Failed to open the file.\n");
        return -1;  // Indicates error
    }

    while(fgets(buf, MAX_BUF, file)) { // Read until end of file. For each line read...
       printf("%s", buf);               // Print the line.
    }

    fclose(file);  // Close the file to free resources.

    return 0; // Indicates success
}
```
Please replace `"/safe/myfile.txt"` with your actual filename, and make sure you have read permissions for this file in the directory where you run the program. Also be careful when working with files as it can lead to security vulnerabilities if not handled properly. It's always a good practice to use absolute paths rather than relative ones.
