    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        user = User.query.filter_by(username=username).first()  # Assuming you have a query method to get the user from your database

        if not user or not user.check_password(password):
            return render_template('login.html', error="Invalid username/password")

        session['user'] = user.username
        return redirect(url_for('change_email'))
    else:
        return render_template('login.html')

@app.route('/logout')
def logout():
    if 'user' in session:
        del session['user']
    return redirect(url_for('login'))

@app.route('/change-email', methods=['GET', 'POST'])
def change_email():
    if not session.get('user'):
        return redirect(url_for('login'))

    user = User.query.filter_by(username=session['user']).first()  # Assuming you have a query method to get the user from your database

    if request.method == 'POST':
        old_email = request.form['old_email']
        new_email = request.form['new_email']
        password = request.form['password']

        if not user.check_password(password):
            return render_template('change-email.html', error="Incorrect password")

        if old_email != user.email:
            return render_template('change-email.html', error="Old email does not match the current one")

        if new_email == old_email:
            return render_template('change-email.html', error="New email must be different from the old one")

        user.set_email(new_email)  # Assuming you have a set method to change the user's email in your database

        return redirect(url_for('login'))
    else:
        return render_template('change-email.html')

if __name__ == '__main__':
    app.run()
```

