users = {
    'user1@example.com': 'password1',
    'user2@example.com': 'password2'
}
```

Then create the Flask application:

```python
from flask import Flask, request, render_template, redirect, url_for, session
app = Flask(__name__)
app.secret_key = "my-super-secret-secrets"

@app.route('/')
def home():
    if 'email' in session:
        return f'Logged in as {session["email"]}'
    else:
        return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form['email']
        password = request.form['password']

        if email in users and users[email] == password:
            session['email'] = email
            return redirect(url_for('home'))
        else:
            return 'Login failed, try again.', 403
    return render_template('login.html')

@app.route('/logout')
def logout():
    session.pop('email', None)
    return redirect(url_for('home'))

@app.route('/change-email', methods=['GET', 'POST'])
def change_email():
    if request.method == 'POST':
        old_email = request.form['old_email']
        new_email = request.form['new_email']
        confirm_password = request.form['confirm_password']

        if session.get('email') != old_email:
            return 'You are not logged in with the provided email', 403

        if users[old_email] != confirm_password:
            return 'Confirm password is incorrect', 403

        users.pop(old_email)
        users[new_email] = confirm_password
        session['email'] = new_email
        return redirect(url_for('home'))
    return render_template('change-email.html')
```

