    free(buffer);
    buffer = NULL;

    return 0;
}
```
Please replace `char *` with your desired data type and `1024` with the size of memory you want to allocate. The malloc function is used for dynamic memory allocation in C, which allocates a block of memory of the specified number of bytes and returns a pointer to its first byte.

In this example we're using only one buffer allocated at the beginning but if you have multiple buffers or need to loop over them, you should manage them with an array of pointers. For instance:

```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    int buffer_size = 1024; // Change this to the size you want
    int num_buffers = 5;  // Change this to the number of buffers you need

    char **buffer = malloc(num_buffers * sizeof(*buffer));

    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for buffers\n");
        return 1;
    }

    // Allocate each buffer individually.
    for(int i = 0; i < num_buffers; i++){
        buffer[i] = malloc(buffer_size);

        if (buffer[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for buffer %d\n", i + 1);

            // If allocation of a buffer fails, free all previously allocated buffers.
            while(--i >= 0){
                free(buffer[i]);
            }

            free(buffer);
            return 1;
        }
    }

    // Use the allocated buffers here...
    // ...

    // Free all allocated buffers.
    for(int i = 0; i < num_buffers; i++){
        free(buffer[i]);
    }

    free(buffer);
    buffer = NULL;

    return 0;
}
```
In this example, the `malloc` function is used to allocate an array of pointers to char. Then each pointer in that array is allocated memory individually with a size of `buffer_size` bytes. After using buffers, we free each buffer and then the array itself. Always remember that you should check if malloc returned NULL before trying to access or write data to the memory it has allocated, because an allocation failure can cause the program to crash.
