['Here's a simple implementation in C that fulfills your requirements. It assumes you have a function `calculateChecksum` which calculates checksums from memory buffers. 

```c
#include <stdio.h>
#include <stdlib.h>

// Assuming calculateChecksum is a function that takes buffer and its size as parameters and returns the checksum.
unsigned int calculateChecksum(const char *buffer, size_t length); 

int main() {
    FILE *fp = fopen("inputFile", "r"); // Open file in read mode
    if (fp == NULL) {
        perror("Unable to open input file!");
        return EXIT_FAILURE;
    }

    fseek(fp, 0L, SEEK_END);      // Jump to the end of the file
    size_t length = ftell(fp);   // Get the current file position (which is equal to the file's size)
    rewind(fp);                  // Go back to the start of the file

    if (length == 0) {           // If file is empty, return error.
        fprintf(stderr, "Input file is empty.\n");
        return EXIT_FAILURE;
    }

    char *buffer = malloc(length);  // Allocate a buffer to hold the content of the file
    if (buffer == NULL) {          // Check for allocation error.
        fprintf(stderr, "Memory allocation failed!\n");
        return EXIT_FAILURE;
    }

    size_t bytesRead = fread(buffer, 1, length, fp);   // Read the file into buffer
    if (bytesRead != length) {                      // Check for read error.
        perror("Unable to read from input file!");
        return EXIT_FAILURE;
    }

    unsigned int checksum = calculateChecksum(buffer, bytesRead);  // Calculate the checksum

    fclose(fp);  // Close the input file.

    FILE *outputFile = fopen("outputFile", "w");  // Open an output file in write mode
    if (outputFile == NULL) {                     // Check for open error.
        perror("Unable to open output file!");
        return EXIT_FAILURE;
    }

    fprintf(outputFile, "Bytes read: %zu\nChecksum: %u", bytesRead, checksum);  // Write the bytes read and checksum to the output file.

    fclose(outputFile);  // Close the output file.
    free(buffer);        // Free the allocated buffer memory.
}
```

Please note that `calculateChecksum` is a placeholder, it should be replaced by your actual checksum calculation function and this example doesn't actually calculate a real checksum but just returns zero to pass the compilation step. 
Also, please handle error scenarios as needed according to your application requirements.
']

['Here's a simple implementation of your request in C using fread, fwrite, and memcmp functions from the standard library. This code assumes that both input and output files can be opened successfully, and it uses unsigned char as buffer type for convenience.

```C
#include <stdio.h>
#include <string.h>

int main() {
    FILE *infile = fopen("input.txt", "r"); // Open the input file in read mode
    if (infile == NULL) {
        printf("Failed to open input file.\n");
        return 1; // Error occurred when opening the file
    }

    unsigned char buffer[256]; // Assume a maximum of 256 bytes can be read at once
    size_t bytesRead = fread(buffer, sizeof(unsigned char), sizeof(buffer), infile);

    if (ferror(infile)) {
        printf("Error reading from input file.\n");
        return 1; // Error occurred when reading from the file
    }

    unsigned char checksum = 0;
    for (size_t i = 0; i < bytesRead; ++i) {
        checksum += buffer[i];
    }

    FILE *outfile = fopen("output.txt", "w"); // Open the output file in write mode
    if (outfile == NULL) {
        printf("Failed to open output file.\n");
        return 1; // Error occurred when opening the file
    }

    // Write number of bytes read and checksum to output file
    fwrite(&bytesRead, sizeof(size_t), 1, outfile);
    fwrite(&checksum, sizeof(unsigned char), 1, outfile);

    if (ferror(outfile)) {
        printf("Error writing to output file.\n");
        return 1; // Error occurred when writing to the file
    }

    fclose(infile);
    fclose(outfile);

    return 0;
}
```
Please ensure to replace "input.txt" and "output.txt" with your actual filenames and also don't forget to handle error cases (e.g., file not found, cannot read from/write to the file). Also note that in this case, I assume you can fit all contents of the input file into a buffer, which might be an issue if your files are very large. For larger files, you would need to adjust this code accordingly, potentially reading and writing chunks of data at a time.
