    if(fd == -1) {
        write(STDOUT_FILENO, "Error opening file!\n", strlen("Error opening file!\n")); 
        return -1;
    }

    // Write to the file
    if(write(fd, str, strlen(str)) == -1) {
        write(STDOUT_FILENO, "Error writing to file!\n", strlen("Error writing to file!\n")); 
        return -1;
    }

    // Close the file
    if(close(fd) == -1) {
        write(STDERR_FILENO, "Error closing file!\n", strlen("Error closing file!\n")); 
        return -1;
    }

    return 0;
}
```

