void trimTrailingSpace(char *str) {
    int index = strlen(str) - 1;
    while (index >= 0 && isspace((unsigned char)str[index])) {
        str[index--] = '\0';
    }
}

int main(int argc, char **argv) {
    if(argc != 2) {
        printf("Error: Exactly one argument needed!\n");
        return -1;
