    int i = 0;
    while (argv[1][i] != '\0') {  // Trim newlines from the string
        if (argv[1][i] == '\n') argv[1][i] = ' ';
        i++;
    }

    printf("Trimmed string: %s\n", argv[1]);

    return 0;
}
```
