['Here's a basic example of how you could implement this in C using httpd (Apache http server):

```c
#include <string.h>
#include "httpd.h"
#include "http_core.h"
#include "http_protocol.h"
#include "http_request.h"

int http_hello_page(struct request_rec *req) {
    char username[1024]; // assuming a max length of 1024 for the username
    char outputbuf[8192]; // assuming a max length of 8192 for the HTML page

    if (!apr_bucket_read(req->input, username, sizeof(username), APR_BLOCK_READ)) {
        return HTTP_INTERNAL_SERVER_ERROR;
    }

    // Here you would normally process the request data to generate the HTML page.
    // For simplicity, we'll just output a simple greeting:
    sprintf(outputbuf, "<html><body>Hello, %s</body></html>", username);

    apr_table_setn(req->headers_out, "Content-Type", "text/html");
    apr_table_setn(req->headers_out, "Content-Length", 
                   apr_psprintf(req->pool, "%d", strlen(outputbuf)));

    if (!is_header_sent(req)) {
        ap_send_http_header(req);
    }

    if (ap_should_client_block(req)) {
        req->rflags |= SHOULD_BLOCK;
    } else {
        req->status = HTTP_OK;
        ap_rputs(outputbuf, req);
        // Indicate we've finished the request.
        req->finish_request();
    }

    return OK;
}
