void escape_html(char *str) {
    char *p = str;
    while (*p) {
        if (*p == '<') fputs("&lt;", stdout);
        else if (*p == '>') fputs("&gt;", stdout);
        else putchar(*p);
        p++;
    }
}

int http_hello_page(void *cls, struct MHD_Connection *connection, 
                    const char *url, const char *method, 
